import re
import os
import json

def load_demos_from_logs():
    """Load all demo pairs from the session logs"""
    session_dir = os.environ.get('RLM_SESSION_DIR', '')
    if not session_dir:
        return {}, "No RLM_SESSION_DIR"

    log_path = os.path.join(session_dir, '../../sessions', os.path.basename(session_dir) + '.jsonl')
    if not os.path.exists(log_path):
        return {}, f"Log path not found: {log_path}"

    demos = {}
    with open(log_path, 'r') as f:
        content = f.read()

    # Find demo pairs and test input
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    matches = list(re.finditer(pattern, content))

    grids = {}
    for m in matches:
        label, h, w = m.groups()
        if label == 'Test input':
            demo_id = f"Test-{h}x{w}"
        else:
            parts = label.split(' ')
            demo_id = parts[0]  # e.g., "Demo pair 1"

        # Extract grid rows after this match
        end_pos = m.end()
        remaining = content[end_pos:end_pos+max(h*w+2, 50)]
        rows = remaining.split('\n')[:h]

        valid_grid = []
        for row in rows:
            stripped = row.strip()
            if stripped:
                row_vals = [int(x) for x in stripped.split()]
                if len(row_vals) == w:
                    valid_grid.append(row_vals)

        if len(valid_grid) == h:
            grids[demo_id] = valid_grid

    return grids, log_path

grids, log_path = load_demos_from_logs()
print(f"Found grids: {list(grids.keys())}")
for k, v in grids.items():
    print(f"\n{k}: {v}")

